//! Error codes and typed access to the parameters of a command.

use serde_json::{Map, Value};

/// The error codes of the protocol; no other code is ever returned.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Code {
    InvalidRequest,
    MissingParameter,
    InvalidParameterValue,
    QueueNameInvalid,
    QueueAlreadyExists,
    QueueDoesNotExist,
    ReceiptHandleInvalid,
    ReceiptHandleExpired,
    UnsupportedOperation,
    LimitExceeded,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error {
    pub code: Code,
    pub message: String,
}

pub type Result<T> = std::result::Result<T, Error>;

impl Error {
    pub fn new(code: Code, message: impl Into<String>) -> Self {
        Self { code, message: message.into() }
    }
}

/// The members of a command, with `null` treated as absent.
#[derive(Clone, Copy)]
pub struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    pub fn new(members: &'a Map<String, Value>) -> Self {
        Self(members)
    }

    pub fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|v| !v.is_null())
    }

    pub fn names(&self) -> impl Iterator<Item = &'a str> + use<'a> {
        let members = self.0;
        members.iter().filter(|(_, v)| !v.is_null()).map(|(k, _)| k.as_str())
    }

    /// Fails with `MissingParameter` for the first of `names` that is absent.
    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|n| self.get(n).is_none()) {
            Some(n) => Err(Error::new(Code::MissingParameter, format!("{n} is required"))),
            None => Ok(()),
        }
    }

    fn invalid(name: &str, want: &str) -> Error {
        Error::new(Code::InvalidParameterValue, format!("{name} must be {want}"))
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|v| v.as_str().ok_or_else(|| Self::invalid(name, "a string")))
            .transpose()
    }

    pub fn required_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?
            .ok_or_else(|| Error::new(Code::MissingParameter, format!("{name} is required")))
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| v.as_bool().ok_or_else(|| Self::invalid(name, "a boolean")))
            .transpose()
    }

    /// An integer within `min..=max`; floats such as `30.0` are not integers.
    pub fn integer(&self, name: &str, min: u32, max: u32) -> Result<Option<u32>> {
        self.get(name)
            .map(|v| {
                v.as_i64()
                    .and_then(|n| u32::try_from(n).ok())
                    .filter(|n| (min..=max).contains(n))
                    .ok_or_else(|| Self::invalid(name, &format!("an integer in {min}..={max}")))
            })
            .transpose()
    }

    pub fn required_integer(&self, name: &str, min: u32, max: u32) -> Result<u32> {
        self.integer(name, min, max)?
            .ok_or_else(|| Error::new(Code::MissingParameter, format!("{name} is required")))
    }

    pub fn object(&self, name: &str) -> Result<Option<Params<'a>>> {
        self.get(name)
            .map(|v| v.as_object().map(Params).ok_or_else(|| Self::invalid(name, "an object")))
            .transpose()
    }

    /// A string of 1 to `max` characters from `A-Z a-z 0-9 _ -`.
    pub fn identifier(&self, name: &str, max: usize) -> Result<Option<&'a str>> {
        match self.string(name)? {
            Some(s) if !(1..=max).contains(&s.chars().count()) || !s.chars().all(is_name_char) => {
                Err(Self::invalid(name, &format!("1 to {max} characters of A-Z a-z 0-9 _ -")))
            }
            other => Ok(other),
        }
    }
}

pub fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

