//! One queue: its attributes, messages, receipt handles and deduplication ids.

use crate::protocol::{Code, Error, Params, Result, is_name_char};
use std::collections::{BTreeMap, BTreeSet, HashMap};

pub const MAX_MESSAGES: usize = 100_000;
const FIFO_SUFFIX: &str = ".fifo";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Attributes {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Attributes {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

/// The attributes a request names; the rest are left as they are.
#[derive(Debug, Default)]
pub struct AttributePatch {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u32>,
}

impl AttributePatch {
    pub fn parse(attributes: Option<Params<'_>>) -> Result<Self> {
        let Some(p) = attributes else { return Ok(Self::default()) };
        const KNOWN: [&str; 7] = [
            "VisibilityTimeout",
            "DelaySeconds",
            "RetentionSeconds",
            "Fifo",
            "ContentBasedDeduplication",
            "DeadLetterQueue",
            "MaxReceiveCount",
        ];
        if let Some(name) = p.names().find(|n| !KNOWN.contains(n)) {
            return Err(Error::new(Code::InvalidParameterValue, format!("unknown attribute {name}")));
        }
        Ok(Self {
            visibility_timeout: p.integer("VisibilityTimeout", 0, 43_200)?,
            delay_seconds: p.integer("DelaySeconds", 0, 900)?,
            retention_seconds: p.integer("RetentionSeconds", 60, 1_209_600)?,
            fifo: p.boolean("Fifo")?,
            content_based_deduplication: p.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?.map(str::to_owned),
            max_receive_count: p.integer("MaxReceiveCount", 1, 1000)?,
        })
    }

    /// The patch's dead-letter configuration; `None` if neither member is present.
    pub fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (&self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => {
                Ok(Some(DeadLetter { queue: queue.clone(), max_receive_count }))
            }
            (None, None) => Ok(None),
            _ => Err(Error::new(
                Code::InvalidParameterValue,
                "DeadLetterQueue and MaxReceiveCount must be given together",
            )),
        }
    }

    /// `base` with the attributes of this patch applied.
    pub fn apply(&self, base: &Attributes, dead_letter: Option<DeadLetter>) -> Attributes {
        Attributes {
            visibility_timeout: self.visibility_timeout.unwrap_or(base.visibility_timeout),
            delay_seconds: self.delay_seconds.unwrap_or(base.delay_seconds),
            retention_seconds: self.retention_seconds.unwrap_or(base.retention_seconds),
            fifo: self.fifo.unwrap_or(base.fifo),
            content_based_deduplication: self
                .content_based_deduplication
                .unwrap_or(base.content_based_deduplication),
            dead_letter: dead_letter.or_else(|| base.dead_letter.clone()),
        }
    }
}

pub fn is_fifo_name(name: &str) -> bool {
    name.ends_with(FIFO_SUFFIX)
}

pub fn is_valid_name(name: &str) -> bool {
    let stem = name.strip_suffix(FIFO_SUFFIX).unwrap_or(name);
    let stem_max = if stem.len() == name.len() { 80 } else { 75 };
    (1..=stem_max).contains(&stem.len()) && stem.chars().all(is_name_char)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Delayed,
    InFlight,
    Visible,
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub group_id: Option<String>,
    pub sent_at: u64,
    pub delayed_until: u64,
    pub in_flight_until: u64,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    /// Number of the latest receipt handle issued for this message.
    pub receipt: Option<u64>,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        if now < self.delayed_until {
            State::Delayed
        } else if now < self.in_flight_until {
            State::InFlight
        } else {
            State::Visible
        }
    }
}

/// A send that was accepted, remembered for deduplication.
#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub message_id: u64,
    pub sequence: u64,
}

#[derive(Debug)]
pub struct Queue {
    pub attributes: Attributes,
    /// Keyed by sequence number, which is also the arrival order.
    pub messages: BTreeMap<u64, Message>,
    /// `(sent_at, sequence)` of every message, so retention only looks at the oldest.
    by_age: BTreeSet<(u64, u64)>,
    /// Latest receipt number to sequence number; entries of gone messages go stale.
    pub receipts: HashMap<u64, u64>,
    pub deduplication: HashMap<String, Accepted>,
    added: u64,
}

impl Queue {
    pub fn new(attributes: Attributes) -> Self {
        Self {
            attributes,
            messages: BTreeMap::new(),
            by_age: BTreeSet::new(),
            receipts: HashMap::new(),
            deduplication: HashMap::new(),
            added: 0,
        }
    }

    /// Adds `message` at the end of the queue and returns its sequence number.
    pub fn push(&mut self, message: Message) -> u64 {
        self.added += 1;
        self.by_age.insert((message.sent_at, self.added));
        self.messages.insert(self.added, message);
        self.added
    }

    pub fn remove(&mut self, sequence: u64) -> Option<Message> {
        let message = self.messages.remove(&sequence)?;
        self.by_age.remove(&(message.sent_at, sequence));
        Some(message)
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.by_age.clear();
        self.receipts.clear();
    }

    /// Drops the messages whose retention has run out at `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.attributes.retention_seconds);
        while let Some(&(sent_at, sequence)) = self.by_age.first() {
            if now < sent_at + retention {
                break;
            }
            self.remove(sequence);
        }
    }

    pub fn count(&self, now: u64, state: State) -> usize {
        self.messages.values().filter(|m| m.state(now) == state).count()
    }
}

