//! The command interpreter: all queues, the virtual clock and the id counters.

use crate::protocol::{Code, Error, Params, Result};
use crate::queue::{
    Accepted, AttributePatch, Attributes, MAX_MESSAGES, Message, Queue, State, is_fifo_name,
    is_valid_name,
};
use serde_json::{Map, Value, json};
use std::collections::{BTreeMap, HashSet};

const MAX_QUEUES: usize = 1000;
const MAX_BODY_BYTES: usize = 1024;
const DEDUPLICATION_WINDOW: u64 = 300;
const MAX_VISIBILITY_TIMEOUT: u32 = 43_200;

#[derive(Default)]
pub struct Broker {
    now: u64,
    queues: BTreeMap<String, Queue>,
    messages_accepted: u64,
    receipts_issued: u64,
}

/// The queue called `name`, with the messages that ran out of retention dropped.
fn lookup<'a>(queues: &'a mut BTreeMap<String, Queue>, now: u64, name: &str) -> Result<&'a mut Queue> {
    let queue = queues
        .get_mut(name)
        .ok_or_else(|| Error::new(Code::QueueDoesNotExist, format!("no queue named {name:?}")))?;
    queue.expire(now);
    Ok(queue)
}

fn invalid(message: &str) -> Error {
    Error::new(Code::InvalidParameterValue, message)
}

impl Broker {
    pub fn new() -> Self {
        Self::default()
    }

    /// Runs one input line and returns its response.
    pub fn handle_line(&mut self, line: &[u8]) -> Value {
        match self.execute(line) {
            Ok(Value::Object(mut members)) => {
                members.insert("ok".into(), Value::Bool(true));
                Value::Object(members)
            }
            Ok(other) => unreachable!("commands return objects, got {other}"),
            Err(e) => json!({"ok": false, "error": {"code": format!("{:?}", e.code), "message": e.message}}),
        }
    }

    fn execute(&mut self, line: &[u8]) -> Result<Value> {
        let bad = |m: &str| Error::new(Code::InvalidRequest, m);
        let text = std::str::from_utf8(line).map_err(|_| bad("line is not UTF-8"))?;
        let value: Value = serde_json::from_str(text).map_err(|e| bad(&format!("not JSON: {e}")))?;
        let members: &Map<String, Value> = value.as_object().ok_or_else(|| bad("not a JSON object"))?;
        let command = members.get("Command").and_then(Value::as_str).ok_or_else(|| bad("no Command string"))?;
        let p = Params::new(members);
        match command {
            "CreateQueue" => self.create_queue(p),
            "SetQueueAttributes" => self.set_queue_attributes(p),
            "GetQueueAttributes" => self.get_queue_attributes(p),
            "ListQueues" => self.list_queues(p),
            "DeleteQueue" => self.delete_queue(p),
            "PurgeQueue" => self.purge_queue(p),
            "Tick" => self.tick(p),
            "SendMessage" => self.send_message(p),
            "ReceiveMessage" => self.receive_message(p),
            "DeleteMessage" => self.delete_message(p),
            "ChangeMessageVisibility" => self.change_message_visibility(p),
            other => Err(bad(&format!("unknown command {other:?}"))),
        }
    }

    fn create_queue(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        if !is_valid_name(name) {
            return Err(Error::new(Code::QueueNameInvalid, format!("{name:?} is not a valid queue name")));
        }
        let patch = AttributePatch::parse(p.object("Attributes")?)?;
        let fifo = patch.fifo.unwrap_or(false);
        if is_fifo_name(name) != fifo {
            return Err(Error::new(Code::QueueNameInvalid, "the .fifo suffix and Fifo must agree"));
        }
        if patch.content_based_deduplication == Some(true) && !fifo {
            return Err(invalid("ContentBasedDeduplication needs a FIFO queue"));
        }
        let attributes = patch.apply(&Attributes::default(), patch.dead_letter()?);
        if let Some(existing) = self.queues.get(name) {
            return if existing.attributes == attributes {
                Ok(json!({}))
            } else {
                Err(Error::new(Code::QueueAlreadyExists, format!("queue {name:?} exists with other attributes")))
            };
        }
        if let Some(dead_letter) = &attributes.dead_letter {
            let target = self.queue_named(&dead_letter.queue)?;
            if target.attributes.fifo != fifo {
                return Err(invalid("the dead-letter queue must be of the same type"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(Code::LimitExceeded, "too many queues"));
        }
        self.queues.insert(name.to_owned(), Queue::new(attributes));
        Ok(json!({}))
    }

    fn queue_named(&self, name: &str) -> Result<&Queue> {
        self.queues
            .get(name)
            .ok_or_else(|| Error::new(Code::QueueDoesNotExist, format!("no queue named {name:?}")))
    }

    fn set_queue_attributes(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName", "Attributes"])?;
        let name = p.required_string("QueueName")?;
        let patch = AttributePatch::parse(p.object("Attributes")?)?;
        let now = self.now;
        let fifo = lookup(&mut self.queues, now, name)?.attributes.fifo;
        if patch.fifo.is_some() {
            return Err(Error::new(Code::UnsupportedOperation, "the type of a queue never changes"));
        }
        if patch.content_based_deduplication == Some(true) && !fifo {
            return Err(invalid("ContentBasedDeduplication needs a FIFO queue"));
        }
        let dead_letter = patch.dead_letter()?;
        if let Some(dead_letter) = &dead_letter {
            let target = self.queue_named(&dead_letter.queue)?;
            if dead_letter.queue == name || target.attributes.fifo != fifo {
                return Err(invalid("the dead-letter queue must be another queue of the same type"));
            }
        }
        let queue = lookup(&mut self.queues, now, name)?;
        queue.attributes = patch.apply(&queue.attributes, dead_letter);
        Ok(json!({}))
    }

    fn get_queue_attributes(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let now = self.now;
        let queue = lookup(&mut self.queues, now, name)?;
        let a = &queue.attributes;
        let mut attributes = json!({
            "VisibilityTimeout": a.visibility_timeout,
            "DelaySeconds": a.delay_seconds,
            "RetentionSeconds": a.retention_seconds,
            "Fifo": a.fifo,
            "ContentBasedDeduplication": a.content_based_deduplication,
        });
        if let Some(d) = &a.dead_letter {
            attributes["DeadLetterQueue"] = json!(d.queue);
            attributes["MaxReceiveCount"] = json!(d.max_receive_count);
        }
        Ok(json!({"Attributes": attributes, "Counts": {
            "Visible": queue.count(now, State::Visible),
            "InFlight": queue.count(now, State::InFlight),
            "Delayed": queue.count(now, State::Delayed),
        }}))
    }

    fn list_queues(&self, p: Params) -> Result<Value> {
        let prefix = p.string("Prefix")?.unwrap_or("");
        let names: Vec<&String> = self.queues.keys().filter(|n| n.starts_with(prefix)).collect();
        Ok(json!({"QueueNames": names}))
    }

    fn delete_queue(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        self.queue_named(name)?;
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.attributes.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.attributes.dead_letter = None;
            }
        }
        Ok(json!({}))
    }

    fn purge_queue(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        lookup(&mut self.queues, self.now, name)?.purge();
        Ok(json!({}))
    }

    fn tick(&mut self, p: Params) -> Result<Value> {
        p.require(&["Seconds"])?;
        self.now += u64::from(p.required_integer("Seconds", 0, 1_209_600)?);
        Ok(json!({"Now": self.now}))
    }

    fn send_message(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName", "Body"])?;
        let name = p.required_string("QueueName")?;
        let body = p.required_string("Body")?;
        if !(1..=MAX_BODY_BYTES).contains(&body.len()) {
            return Err(invalid("Body must be 1 to 1024 bytes"));
        }
        let delay = p.integer("DelaySeconds", 0, 900)?;
        let group_id = p.identifier("GroupId", 128)?;
        let deduplication_id = p.identifier("DeduplicationId", 128)?;

        let now = self.now;
        let queue = lookup(&mut self.queues, now, name)?;
        let fifo = queue.attributes.fifo;
        if (!fifo && (group_id.is_some() || deduplication_id.is_some())) || (fifo && delay.is_some()) {
            return Err(Error::new(Code::UnsupportedOperation, "not supported by this type of queue"));
        }
        let missing = |what: &str| Error::new(Code::MissingParameter, format!("{what} is required"));
        let mut key = None;
        if fifo {
            group_id.ok_or_else(|| missing("GroupId"))?;
            let content_key = queue.attributes.content_based_deduplication.then_some(body);
            let k = deduplication_id.or(content_key).ok_or_else(|| missing("DeduplicationId"))?;
            if let Some(original) = queue.deduplication.get(k)
                && now - original.at < DEDUPLICATION_WINDOW
            {
                return Ok(sent(original.message_id, fifo.then_some(original.sequence)));
            }
            key = Some(k);
        }
        if queue.messages.len() >= MAX_MESSAGES {
            return Err(Error::new(Code::LimitExceeded, "queue is full"));
        }
        self.messages_accepted += 1;
        let id = self.messages_accepted;
        let delay = u64::from(delay.unwrap_or(queue.attributes.delay_seconds));
        let sequence = queue.push(Message {
            id,
            body: body.to_owned(),
            group_id: group_id.map(str::to_owned),
            sent_at: now,
            delayed_until: now + delay,
            in_flight_until: 0,
            receive_count: 0,
            first_received_at: None,
            receipt: None,
        });
        if let Some(key) = key {
            queue.deduplication.insert(key.to_owned(), Accepted { at: now, message_id: id, sequence });
        }
        Ok(sent(id, fifo.then_some(sequence)))
    }

    fn receive_message(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName"])?;
        let name = p.required_string("QueueName")?;
        let max = p.integer("MaxMessages", 1, 10)?.unwrap_or(1) as usize;
        let visibility = p.integer("VisibilityTimeout", 0, MAX_VISIBILITY_TIMEOUT)?;

        let now = self.now;
        let queue = lookup(&mut self.queues, now, name)?;
        let visibility = u64::from(visibility.unwrap_or(queue.attributes.visibility_timeout));
        let fifo = queue.attributes.fifo;
        let dead_letter = queue.attributes.dead_letter.clone();
        // Groups that still have an earlier message in the queue.
        let mut blocked_groups: HashSet<String> = HashSet::new();
        let mut delivered = Vec::new();
        let mut to_move = Vec::new();
        for (&sequence, m) in queue.messages.iter_mut() {
            if delivered.len() == max {
                break;
            }
            let blocked = m.group_id.as_ref().is_some_and(|g| blocked_groups.contains(g));
            let moves = dead_letter.as_ref().is_some_and(|d| m.receive_count >= d.max_receive_count);
            if !blocked && m.state(now) == State::Visible && moves {
                to_move.push(sequence);
                continue;
            }
            if let Some(group) = &m.group_id {
                blocked_groups.insert(group.clone());
            }
            if blocked || m.state(now) != State::Visible {
                continue;
            }
            self.receipts_issued += 1;
            let receipt = self.receipts_issued;
            if let Some(old) = m.receipt.replace(receipt) {
                queue.receipts.remove(&old);
            }
            queue.receipts.insert(receipt, sequence);
            m.receive_count += 1;
            m.first_received_at.get_or_insert(now);
            m.in_flight_until = now + visibility;
            let mut entry = json!({
                "MessageId": format!("m-{}", m.id),
                "ReceiptHandle": format!("r-{receipt}"),
                "Body": m.body,
                "ReceiveCount": m.receive_count,
                "SentAt": m.sent_at,
                "FirstReceivedAt": m.first_received_at,
            });
            if fifo {
                entry["GroupId"] = json!(m.group_id);
                entry["SequenceNumber"] = json!(sequence);
            }
            delivered.push(entry);
        }
        let moved: Vec<Message> = to_move.into_iter().filter_map(|s| queue.remove(s)).collect();
        if let Some(dead_letter) = dead_letter {
            let target = lookup(&mut self.queues, now, &dead_letter.queue)?;
            for mut message in moved {
                message.receive_count = 0;
                message.first_received_at = None;
                message.receipt = None;
                message.delayed_until = 0;
                message.in_flight_until = 0;
                target.push(message);
            }
            target.expire(now);
        }
        Ok(json!({"Messages": delivered}))
    }

    /// Finds the in-flight message that `receipt` is the latest handle of.
    fn locate(&mut self, p: Params) -> Result<(&mut Queue, u64, u64)> {
        let name = p.required_string("QueueName")?;
        let handle = p.required_string("ReceiptHandle")?;
        let now = self.now;
        let issued = self.receipts_issued;
        let queue = lookup(&mut self.queues, now, name)?;
        let number = handle
            .strip_prefix("r-")
            .filter(|n| !n.starts_with('0') && n.bytes().all(|b| b.is_ascii_digit()))
            .and_then(|n| n.parse::<u64>().ok())
            .filter(|n| (1..=issued).contains(n))
            .ok_or_else(|| Error::new(Code::ReceiptHandleInvalid, format!("{handle:?} was never issued")))?;
        let sequence = queue
            .receipts
            .get(&number)
            .copied()
            .filter(|s| {
                queue.messages.get(s).is_some_and(|m| m.receipt == Some(number) && m.state(now) == State::InFlight)
            })
            .ok_or_else(|| Error::new(Code::ReceiptHandleExpired, format!("{handle:?} is no longer usable")))?;
        Ok((queue, sequence, number))
    }

    fn delete_message(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName", "ReceiptHandle"])?;
        p.required_string("QueueName")?;
        p.required_string("ReceiptHandle")?;
        let (queue, sequence, number) = self.locate(p)?;
        queue.remove(sequence);
        queue.receipts.remove(&number);
        Ok(json!({}))
    }

    fn change_message_visibility(&mut self, p: Params) -> Result<Value> {
        p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
        p.required_string("QueueName")?;
        p.required_string("ReceiptHandle")?;
        let timeout = u64::from(p.required_integer("VisibilityTimeout", 0, MAX_VISIBILITY_TIMEOUT)?);
        let now = self.now;
        let (queue, sequence, _) = self.locate(p)?;
        if let Some(message) = queue.messages.get_mut(&sequence) {
            message.in_flight_until = now + timeout;
        }
        Ok(json!({}))
    }
}

fn sent(message_id: u64, sequence: Option<u64>) -> Value {
    let mut result = json!({"MessageId": format!("m-{message_id}")});
    if let Some(sequence) = sequence {
        result["SequenceNumber"] = json!(sequence);
    }
    result
}

