//! End-to-end tests: each runs the `miniq` binary on a script of input lines.

use serde_json::{Value, json};
use std::io::Write;
use std::process::{Command, Stdio};

fn run_raw(input: &[u8]) -> Vec<Value> {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("spawn miniq");
    child.stdin.take().expect("stdin").write_all(input).expect("write");
    let out = child.wait_with_output().expect("wait");
    assert!(out.status.success());
    String::from_utf8(out.stdout)
        .expect("utf-8 output")
        .lines()
        .map(|l| serde_json::from_str(l).expect("one JSON object per line"))
        .collect()
}

fn run(commands: &[Value]) -> Vec<Value> {
    let input: String = commands.iter().map(|c| format!("{c}\n")).collect();
    run_raw(input.as_bytes())
}

fn code(response: &Value) -> &str {
    assert_eq!(response["ok"], false, "{response}");
    response["error"]["code"].as_str().expect("code")
}

fn create(name: &str, attributes: Value) -> Value {
    json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes})
}

fn send(queue: &str, body: &str) -> Value {
    json!({"Command": "SendMessage", "QueueName": queue, "Body": body})
}

fn receive(queue: &str) -> Value {
    json!({"Command": "ReceiveMessage", "QueueName": queue})
}

fn tick(seconds: u32) -> Value {
    json!({"Command": "Tick", "Seconds": seconds})
}

#[test]
fn every_line_gets_one_response_and_bad_lines_are_invalid_requests() {
    let r = run_raw(b"\n[]\n{\"Command\":1}\n{\"Command\":\"Nope\"}\n\xff\n{\"Command\":\"Tick\",\"Seconds\":5}");
    let codes: Vec<&str> = r[..5].iter().map(code).collect();
    assert_eq!(codes, ["InvalidRequest"; 5]);
    assert_eq!(r[5], json!({"ok": true, "Now": 5}));
    assert_eq!(r.len(), 6);
}

#[test]
fn integers_must_be_written_without_fraction_or_exponent() {
    let r = run_raw(b"{\"Command\":\"Tick\",\"Seconds\":30.0}\n{\"Command\":\"Tick\",\"Seconds\":3e1}\n{\"Command\":\"Tick\",\"Seconds\":\"3\"}\n{\"Command\":\"Tick\"}\n");
    let codes: Vec<&str> = r.iter().map(code).collect();
    assert_eq!(codes, ["InvalidParameterValue", "InvalidParameterValue", "InvalidParameterValue", "MissingParameter"]);
}

#[test]
fn create_queue_is_idempotent_only_for_equal_attributes() {
    let r = run(&[
        create("a", json!({})),
        create("a", json!({"VisibilityTimeout": 30, "DelaySeconds": null})),
        create("a", json!({"VisibilityTimeout": 31})),
        create("b.fifo", json!({})),
        create("b.fifo", json!({"Fifo": true, "ContentBasedDeduplication": true})),
        create("b.fifo", json!({"Fifo": true, "ContentBasedDeduplication": 1})),
        create("x.fifo.fifo", json!({"Fifo": true})),
        create("c", json!({"ContentBasedDeduplication": true})),
        create("c", json!({"DeadLetterQueue": "a"})),
        create("c", json!({"DeadLetterQueue": "zz", "MaxReceiveCount": 2})),
        create("c", json!({"DeadLetterQueue": "b.fifo", "MaxReceiveCount": 2})),
    ]);
    let results: Vec<&str> = r.iter().map(|v| v["error"]["code"].as_str().unwrap_or("ok")).collect();
    assert_eq!(
        results,
        [
            "ok",
            "ok",
            "QueueAlreadyExists",
            "QueueNameInvalid",
            "ok",
            "QueueAlreadyExists",
            "QueueNameInvalid",
            "InvalidParameterValue",
            "InvalidParameterValue",
            "QueueDoesNotExist",
            "InvalidParameterValue",
        ]
    );
}

#[test]
fn list_queues_sorts_by_bytes_and_filters_by_prefix() {
    let r = run(&[
        create("b", json!({})),
        create("a_", json!({})),
        create("A1", json!({})),
        create("a-", json!({})),
        json!({"Command": "ListQueues"}),
        json!({"Command": "ListQueues", "Prefix": "a"}),
    ]);
    assert_eq!(r[4]["QueueNames"], json!(["A1", "a-", "a_", "b"]));
    assert_eq!(r[5]["QueueNames"], json!(["a-", "a_"]));
}

#[test]
fn visibility_timeout_hides_a_message_and_its_old_handle_expires() {
    let r = run(&[
        create("q", json!({"VisibilityTimeout": 10})),
        send("q", "hi"),
        receive("q"),
        receive("q"),
        tick(10),
        receive("q"),
        json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-1"}),
        json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-01"}),
        json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-2"}),
        receive("q"),
    ]);
    assert_eq!(r[1], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(r[2]["Messages"][0]["ReceiptHandle"], "r-1");
    assert_eq!(r[3]["Messages"], json!([]));
    assert_eq!(r[5]["Messages"][0]["ReceiveCount"], 2);
    assert_eq!(r[5]["Messages"][0]["FirstReceivedAt"], 0);
    assert_eq!(code(&r[6]), "ReceiptHandleExpired");
    assert_eq!(code(&r[7]), "ReceiptHandleInvalid");
    assert_eq!(r[8], json!({"ok": true}));
    assert_eq!(r[9]["Messages"], json!([]));
}

#[test]
fn delayed_and_retained_messages_follow_the_clock() {
    let r = run(&[
        create("q", json!({"DelaySeconds": 5, "RetentionSeconds": 60})),
        send("q", "x"),
        json!({"Command": "GetQueueAttributes", "QueueName": "q"}),
        tick(5),
        json!({"Command": "GetQueueAttributes", "QueueName": "q"}),
        tick(55),
        json!({"Command": "GetQueueAttributes", "QueueName": "q"}),
    ]);
    assert_eq!(r[2]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 1}));
    assert_eq!(r[4]["Counts"], json!({"Visible": 1, "InFlight": 0, "Delayed": 0}));
    assert_eq!(r[6]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn fifo_deduplicates_for_300_seconds_and_blocks_groups() {
    let fifo_send = |body: &str, group: &str, dedup: &str| {
        json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": body, "GroupId": group, "DeduplicationId": dedup})
    };
    let r = run(&[
        create("f.fifo", json!({"Fifo": true})),
        fifo_send("a", "g1", "d1"),
        fifo_send("again", "g2", "d1"),
        fifo_send("b", "g1", "d2"),
        fifo_send("c", "g2", "d3"),
        json!({"Command": "ReceiveMessage", "QueueName": "f.fifo", "MaxMessages": 10}),
        tick(300),
        fifo_send("a2", "g1", "d1"),
        send("f.fifo", "no group"),
    ]);
    assert_eq!(r[1], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(r[2], r[1]);
    assert_eq!(r[3]["SequenceNumber"], 2);
    let bodies: Vec<&Value> = r[5]["Messages"].as_array().unwrap().iter().map(|m| &m["Body"]).collect();
    assert_eq!(bodies, ["a", "c"]);
    assert_eq!(r[7], json!({"ok": true, "MessageId": "m-4", "SequenceNumber": 4}));
    assert_eq!(code(&r[8]), "MissingParameter");
}

#[test]
fn dead_letter_move_resets_the_message_and_unblocks_nothing_else() {
    let r = run(&[
        create("dlq", json!({})),
        create("q", json!({"DeadLetterQueue": "dlq", "MaxReceiveCount": 1, "VisibilityTimeout": 0})),
        send("q", "poison"),
        receive("q"),
        receive("q"),
        receive("dlq"),
        json!({"Command": "DeleteQueue", "QueueName": "dlq"}),
        json!({"Command": "GetQueueAttributes", "QueueName": "q"}),
    ]);
    assert_eq!(r[3]["Messages"][0]["ReceiveCount"], 1);
    assert_eq!(r[4]["Messages"], json!([]));
    let moved = &r[5]["Messages"][0];
    assert_eq!((moved["MessageId"].as_str(), moved["ReceiveCount"].as_u64()), (Some("m-1"), Some(1)));
    assert_eq!(r[7]["Attributes"].get("DeadLetterQueue"), None);
}

#[test]
fn checks_run_in_the_documented_order() {
    let r = run(&[
        json!({"Command": "SendMessage", "QueueName": 5}),
        json!({"Command": "SendMessage", "QueueName": "nope", "Body": "x"}),
        json!({"Command": "DeleteMessage", "QueueName": "nope", "ReceiptHandle": "junk"}),
        create("q", json!({"Fifo": "yes", "Bogus": 1})),
        create("bad name", json!({"Fifo": "yes"})),
        json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {}}),
    ]);
    let codes: Vec<&str> = r.iter().map(code).collect();
    assert_eq!(
        codes,
        ["MissingParameter", "QueueDoesNotExist", "QueueDoesNotExist", "InvalidParameterValue", "QueueNameInvalid", "QueueDoesNotExist"]
    );
}

#[test]
fn filling_a_queue_to_its_limit_is_fast() {
    let mut commands = vec![create("q", json!({}))];
    commands.extend((0..100_001).map(|_| send("q", "x")));
    let started = std::time::Instant::now();
    let r = run(&commands);
    assert!(started.elapsed().as_secs() < 20);
    assert_eq!(r[100_000]["MessageId"], "m-100000");
    assert_eq!(code(&r[100_001]), "LimitExceeded");
}

