//! End-to-end tests: each runs the `miniq` binary on a script of input lines.

use serde_json::{Value, json};
use std::io::Write;
use std::process::{Command, Stdio};

fn run_raw(input: &[u8]) -> Vec<Value> {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("spawn miniq");
    child.stdin.take().expect("stdin").write_all(input).expect("write");
    let out = child.wait_with_output().expect("wait");
    assert!(out.status.success());
    String::from_utf8(out.stdout)
        .expect("utf-8 output")
        .lines()
        .map(|l| serde_json::from_str(l).expect("one JSON object per line"))
        .collect()
}

fn run(commands: &[Value]) -> Vec<Value> {
    let input: String = commands.iter().map(|c| format!("{c}\n")).collect();
    run_raw(input.as_bytes())
}

fn code(response: &Value) -> &str {
    assert_eq!(response["ok"], false, "{response}");
    response["error"]["code"].as_str().expect("code")
}

fn create(name: &str, attributes: Value) -> Value {
    json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes})
}

fn send(queue: &str, body: &str) -> Value {
    json!({"Command": "SendMessage", "QueueName": queue, "Body": body})
}

fn receive(queue: &str) -> Value {
    json!({"Command": "ReceiveMessage", "QueueName": queue})
}

fn tick(seconds: u32) -> Value {
    json!({"Command": "Tick", "Seconds": seconds})
}

#[test]
fn every_line_gets_one_response_and_bad_lines_are_invalid_requests() {
    let r = run_raw(b"\n[]\n{\"Command\":1}\n{\"Command\":\"Nope\"}\n\xff\n{\"Command\":\"Tick\",\"Seconds\":5}");
    let codes: Vec<&str> = r[..5].iter().map(code).collect();
    assert_eq!(codes, ["InvalidRequest"; 5]);
    assert_eq!(r[5], json!({"ok": true, "Now": 5}));
    assert_eq!(r.len(), 6);
}

#[test]
fn integers_must_be_written_without_fraction_or_exponent() {
    let r = run_raw(b"{\"Command\":\"Tick\",\"Seconds\":30.0}\n{\"Command\":\"Tick\",\"Seconds\":3e1}\n{\"Command\":\"Tick\",\"Seconds\":\"3\"}\n{\"Command\":\"Tick\"}\n");
    let codes: Vec<&str> = r.iter().map(code).collect();
    assert_eq!(codes, ["InvalidParameterValue", "InvalidParameterValue", "InvalidParameterValue", "MissingParameter"]);
}

#[test]
fn create_queue_is_idempotent_only_for_equal_attributes() {
    let r = run(&[
        create("a", json!({})),
        create("a", json!({"VisibilityTimeout": 30, "DelaySeconds": null})),
        create("a", json!({"VisibilityTimeout": 31})),
        create("b.fifo", json!({})),
        create("b.fifo", json!({"Fifo": true, "ContentBasedDeduplication": true})),
        create("b.fifo", json!({"Fifo": true, "ContentBasedDeduplication": 1})),
        create("x.fifo.fifo", json!({"Fifo": true})),
        create("c", json!({"ContentBasedDeduplication": true})),
        create("c", json!({"DeadLetterQueue": "a"})),
        create("c", json!({"DeadLetterQueue": "zz", "MaxReceiveCount": 2})),
        create("c", json!({"DeadLetterQueue": "b.fifo", "MaxReceiveCount": 2})),
    ]);
    let results: Vec<&str> = r.iter().map(|v| v["error"]["code"].as_str().unwrap_or("ok")).collect();
    assert_eq!(
        results,
        [
            "ok",
            "ok",
            "QueueAlreadyExists",
            "QueueNameInvalid",
            "ok",
            "QueueAlreadyExists",
            "QueueNameInvalid",
            "InvalidParameterValue",
            "InvalidParameterValue",
            "QueueDoesNotExist",
            "InvalidParameterValue",
        ]
    );
}

#[test]
fn list_queues_sorts_by_bytes_and_filters_by_prefix() {
    let r = run(&[
        create("b", json!({})),
        create("a_", json!({})),
        create("A1", json!({})),
        create("a-", json!({})),
        json!({"Command": "ListQueues"}),
        json!({"Command": "ListQueues", "Prefix": "a"}),
    ]);
    assert_eq!(r[4]["QueueNames"], json!(["A1", "a-", "a_", "b"]));
    assert_eq!(r[5]["QueueNames"], json!(["a-", "a_"]));
}

#[test]
fn visibility_timeout_hides_a_message_and_its_old_handle_expires() {
    let r = run(&[
        create("q", json!({"VisibilityTimeout": 10})),
